'use strict';
const api='../api/index.php';
const steps=[['BOOKED','ยืนยันการจอง'],['CHECKED_IN','เช็กอินแล้ว'],['REGISTRATION_WAITING','รอเวชระเบียน'],['VISIT_OPEN','เปิด Visit แล้ว'],['SERVICE_WAITING','รอรับบริการ'],['SERVING','กำลังรับบริการ'],['COMPLETED','เสร็จสิ้น']];
const titles={BOOKED:'จองคิวเรียบร้อยแล้ว',REGISTRATION_WAITING:'กำลังรอเวชระเบียน',VISIT_OPEN:'เปิด Visit แล้ว',SERVICE_WAITING:'กำลังรอรับบริการ',SERVING:'กำลังรับบริการ',COMPLETED:'รับบริการเสร็จสิ้น'};
let activeToken='';
const $=id=>document.getElementById(id);
function thaiDate(value){if(!value)return '—';const d=new Date(value.includes('T')?value:`${value}T12:00:00+07:00`);return new Intl.DateTimeFormat('th-TH-u-ca-buddhist',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Bangkok'}).format(d)}
function currentIndex(step){const aliases={WAITING:'REGISTRATION_WAITING',CALLED:'REGISTRATION_WAITING',CHECKED_IN:'REGISTRATION_WAITING'};return Math.max(0,steps.findIndex(x=>x[0]===(aliases[step]||step)))}
async function loadStatus(token){activeToken=token.trim();$('lookupError').classList.add('hidden');try{const response=await fetch(`${api}?action=queue-status&token=${encodeURIComponent(activeToken)}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error||'ไม่พบข้อมูลคิว');render(body.data);history.replaceState(null,'',`?t=${encodeURIComponent(activeToken)}`)}catch(error){$('lookupCard').classList.remove('hidden');$('statusCard').classList.add('hidden');$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden')}}
function render(data){$('lookupCard').classList.add('hidden');$('statusCard').classList.remove('hidden');$('queueNo').textContent=data.queue_no||'ยังไม่ออกคิว';$('customer').textContent=data.customer_display;$('location').textContent=`${data.branch_name} · ${data.department_name}`;$('service').textContent=data.service_name||data.department_name;$('reference').textContent=`${data.reference_no} · นัดหมาย ${thaiDate(data.slot_date)} เวลา ${data.start_time} น.`;$('statusTitle').textContent=titles[data.current_step]||'กำลังดำเนินการ';$('waitTime').textContent=data.estimated_wait_minutes===null?'กำลังประเมิน':data.estimated_wait_minutes<=0?'ใกล้ถึงคิว':`ประมาณ ${data.estimated_wait_minutes} นาที`;$('nextAction').textContent=data.current_step==='BOOKED'?'กรุณาเช็กอินที่ Kiosk เมื่อมาถึง':data.current_step==='COMPLETED'?'การรับบริการรายการนี้เสร็จแล้ว':'โปรดติดตามการเรียกคิวและคำแนะนำ';const index=currentIndex(data.current_step);$('timeline').innerHTML=steps.map((s,i)=>`<li class="step ${i<index?'done':i===index?'current':''}"><div class="step-mark">${i<index?'✓':i+1}</div><div><strong>${s[1]}</strong><span>${i<index?'ดำเนินการแล้ว':i===index?'ขั้นตอนปัจจุบัน':'รอดำเนินการ'}</span></div></li>`).join('')}
$('lookupForm').onsubmit=e=>{e.preventDefault();loadStatus($('tokenInput').value)};$('refreshButton').onclick=()=>loadStatus(activeToken);$('newLookup').onclick=()=>{history.replaceState(null,'',location.pathname);$('statusCard').classList.add('hidden');$('lookupCard').classList.remove('hidden');$('tokenInput').value='';$('tokenInput').focus()};
function updateClock(){$('clock').textContent=new Intl.DateTimeFormat('th-TH-u-ca-buddhist',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Asia/Bangkok'}).format(new Date())+' น.'}updateClock();setInterval(updateClock,30000);const initial=new URLSearchParams(location.search).get('t');if(initial)loadStatus(initial);
